-- =====================================================================
-- 16_app_catalog.sql — Master data used by the WAMWins app (generated from the app's data.js)
-- Gives every system food and recipe a stable code shared with the app, adds the app's foods,
-- local-language aliases, allergens, diet exclusions and the starter recipe library.
-- Run AFTER 15_supabase.sql. Safe to re-run.
-- =====================================================================

-- foods: tag existing seed rows by name, then add the missing ones

create temp table app_foods(code text, name text, cat text, unit text, loc text, life int) on commit drop;

