update ref.food_items fi set code = a.code from app_foods a where fi.household_id is null and fi.code is null and lower(fi.name) = lower(a.name);
insert into ref.food_items(code, name, category_id, default_unit_id, default_location_type_id, shelf_life_days, is_system)
  select a.code, a.name, c.id, u.id, l.id, a.life, true from app_foods a
  join ref.food_categories c on c.code = a.cat join ref.units u on u.code = a.unit left join ref.location_types l on l.code = a.loc
  where not exists (select 1 from ref.food_items x where x.household_id is null and (x.code = a.code or lower(x.name) = lower(a.name)));

