insert into ref.food_item_allergens(food_item_id, allergen_id, presence)
  select fi.id, a.id, 'contains' from (values ('eggs','egg'),('milk','milk'),('milk','lactose'),('cheddar','milk'),('cheddar','lactose'),('mozzarella','milk'),('mozzarella','lactose'),('parmesan','milk'),('butter','milk'),('yogurt','milk'),('yogurt','lactose'),('cream','milk'),('cream','lactose'),('salmon','fish'),('tuna','fish'),('shrimp','shellfish'),('tofu','soy'),('pasta','wheat'),('pasta','gluten'),('bread','wheat'),('bread','gluten'),('flour','wheat'),('flour','gluten'),('oats','gluten'),('tortillas','wheat'),('tortillas','gluten'),('sesameoil','sesame'),('peanutbutter','peanuts'),('soysauce','soy'),('soysauce','wheat'),('soysauce','gluten'),('almonds','tree_nuts'),('peanuts','peanuts'),('crackers','wheat'),('crackers','gluten'),('icecream','milk'),('icecream','lactose')) v(code, al)
  join ref.food_items fi on fi.code = v.code join ref.allergens a on a.code = v.al
  on conflict do nothing;

-- diet exclusions at item level (vegan honey, halal / kosher items) — starter rules, review with an adviser

insert into ref.dietary_requirement_exclusions(requirement_type_id, food_item_id)
  select t.id, fi.id from (values ('vegan','honey'),('halal','pork'),('halal','ham'),('halal','sausage'),('kosher','pork'),('kosher','ham'),('kosher','sausage'),('kosher','shrimp')) v(d, f)
  join ref.dietary_requirement_types t on t.code = v.d join ref.food_items fi on fi.code = v.f
  where not exists (select 1 from ref.dietary_requirement_exclusions x where x.requirement_type_id = t.id and x.food_item_id = fi.id);

-- recipes

insert into ref.recipes(code, title, servings, cook_minutes, steps, is_system, is_published) values
 ('veg_pasta','Creamy Veggie Pasta',4,25,'["Boil the pasta in salted water until al dente.","Sauté garlic in olive oil, add chopped tomatoes and spinach until wilted.","Stir in cream and parmesan, then toss with the drained pasta."]'::jsonb,true,true),
 ('peanut_noodles','Peanut Noodles',4,20,'["Soak or boil the rice noodles; drain and rinse.","Whisk peanut butter, soy sauce, lime juice, grated garlic and warm water.","Toss noodles with sauce, shredded carrot and cucumber."]'::jsonb,true,true),
 ('oven_eggs','Oven Baked Eggs',3,20,'["Heat the oven to 190 °C / 375 °F.","Layer spinach and tomato in an oiled dish, crack in the eggs.","Top with cheese and bake 12–15 minutes."]'::jsonb,true,true),
 ('salmon_bowl','Salmon Rice Bowl',4,30,'["Cook the rice.","Pan-sear the salmon 4 minutes per side.","Serve over rice with sliced cucumber, avocado and soy sauce."]'::jsonb,true,true),
 ('chicken_stirfry','Chicken Stir-Fry',4,25,'["Cook the rice.","Stir-fry sliced chicken until golden; remove.","Stir-fry vegetables with garlic and ginger, return chicken, add soy sauce."]'::jsonb,true,true),
 ('bean_tacos','Black Bean Tacos',4,20,'["Warm the beans with diced onion and a pinch of salt.","Warm tortillas in a dry pan.","Fill with beans, tomato, avocado, cilantro and a squeeze of lime."]'::jsonb,true,true),
 ('lentil_soup','Lentil Soup',6,40,'["Sauté onion, carrot and garlic in olive oil.","Add lentils, tomatoes and broth; simmer 25–30 minutes.","Season and serve."]'::jsonb,true,true),
 ('spanish_omelette','Spanish Omelette',4,35,'["Slowly fry thin potato and onion slices in olive oil until soft.","Mix with beaten eggs and salt.","Cook in a pan until set, flip with a plate and finish."]'::jsonb,true,true),
 ('rice_beans','Arroz com Feijão',6,45,'["Sauté garlic and onion, add rice, toast 1 minute, add water and cook.","Heat the beans with a little garlic and salt.","Serve together."]'::jsonb,true,true),
 ('overnight_oats','Overnight Oats',2,5,'["Mix oats, milk and yogurt in a jar.","Refrigerate overnight.","Top with berries and honey."]'::jsonb,true,true),
 ('banana_pancakes','Banana Pancakes',4,25,'["Mash bananas, whisk in eggs and milk.","Fold in flour and sugar.","Cook ladlefuls in a buttered pan until golden on both sides."]'::jsonb,true,true),
 ('chicken_adobo','Chicken Adobo',5,50,'["Marinate chicken with soy sauce, garlic and pepper.","Brown the chicken, add marinade, onion and a cup of water.","Simmer 30 minutes; serve with rice."]'::jsonb,true,true),
 ('roast_chicken','Roast Chicken & Potatoes',5,60,'["Heat the oven to 200 °C / 400 °F.","Toss chicken, potatoes, carrots, garlic and lemon with oil and salt.","Roast 45 minutes, turning once."]'::jsonb,true,true),
 ('tuna_salad','Tuna Salad',3,10,'["Chop the lettuce, tomato and cucumber.","Add flaked tuna.","Dress with olive oil and lemon."]'::jsonb,true,true),
 ('garlic_shrimp','Garlic Shrimp Rice',4,25,'["Cook the rice.","Sauté garlic in butter, add shrimp and cook until pink.","Finish with lemon and serve over rice."]'::jsonb,true,true),
 ('bolognese','Beef Bolognese',5,45,'["Brown the beef with onion, carrot and garlic.","Add tomato sauce and simmer 25 minutes.","Serve over pasta with parmesan."]'::jsonb,true,true),
 ('chickpea_curry','Chickpea Curry',4,35,'["Cook the rice.","Sauté onion, garlic and ginger; add tomatoes and chickpeas.","Simmer 15 minutes, stir in spinach."]'::jsonb,true,true),
 ('tofu_stirfry','Tofu Veggie Stir-Fry',4,25,'["Prepare the noodles.","Crisp cubed tofu in a hot pan.","Add vegetables, sauce and noodles; toss."]'::jsonb,true,true),
 ('airfryer_tenders','Air-Fryer Chicken Tenders',4,25,'["Cut chicken into strips; dip in egg then seasoned flour.","Air-fry at 200 °C / 400 °F for 10–12 minutes, turning once."]'::jsonb,true,true),
 ('berry_smoothie','Banana Berry Smoothie',2,5,'["Blend everything until smooth."]'::jsonb,true,true),
 ('ham_toastie','Ham & Cheese Toastie',2,10,'["Butter the outsides of the bread.","Fill with ham and cheese.","Toast in a pan until golden and melted."]'::jsonb,true,true),
 ('veggie_frittata','Zucchini Frittata',4,25,'["Sauté sliced zucchini and onion.","Pour over beaten eggs with parmesan.","Cook covered on low heat until set."]'::jsonb,true,true)
  on conflict (code) where code is not null do update set title = excluded.title, servings = excluded.servings, cook_minutes = excluded.cook_minutes, steps = excluded.steps;

