insert into ref.recipe_appliance_requirements(recipe_id, appliance_type_id, is_required)
  select r.id, a.id, true from (values ('veg_pasta','range'),('peanut_noodles','range'),('oven_eggs','oven'),('salmon_bowl','range'),('chicken_stirfry','range'),('bean_tacos','range'),('lentil_soup','range'),('spanish_omelette','range'),('rice_beans','range'),('banana_pancakes','range'),('chicken_adobo','range'),('roast_chicken','oven'),('garlic_shrimp','range'),('bolognese','range'),('chickpea_curry','range'),('tofu_stirfry','range'),('airfryer_tenders','air_fryer'),('berry_smoothie','blender'),('ham_toastie','range'),('veggie_frittata','range')) v(rc, ac)
  join ref.recipes r on r.code = v.rc join ref.appliance_types a on a.code = v.ac
  on conflict (recipe_id, appliance_type_id) do nothing;

